from pathlib import Path
w=Path('.work/vtm')
s=(w/'test_tangential_production_loop_v1.py').read_text().replace('import hashlib,json,subprocess','import hashlib,json,os,subprocess')
s=s.replace("out=w/'tangential-production-loop-v1'", "out=Path(os.environ.get('WARPOWER_TOPOLOGY_LOOP_OUTPUT',str(w/'tangential-production-loop-v2')))")
s=s.replace('old_count:wp.array[int],volume:', 'old_count:wp.array[int],child_points:wp.array[int],child_full:wp.array[int],child_retained:wp.array[int],volume:')
s=s.replace('values[r,0]=volume[0]', 'rows[r,21]=child_points[0];rows[r,22]=child_full[0];rows[r,23]=child_retained[0]\n    values[r,0]=volume[0]')
s=s.replace('rows=wp.empty((5,21)', 'rows=wp.empty((5,24)')
s=s.replace('r.status,r._old_count,volume', 'r.status,r._old_count,r.point_count,r.full_count,r.retained_count,volume')
s=s.replace('    with monkeypatch.context() as patch:', "    profiler=None\n    if os.environ.get('WARPOWER_TOPOLOGY_NSYS'):\n        import torch\n        profiler=torch.cuda.cudart()\n    with monkeypatch.context() as patch:")
s=s.replace('        wp.capture_launch(cap.graph,stream=stream)', '        if profiler is not None:profiler.cudaProfilerStart()\n        wp.capture_launch(cap.graph,stream=stream)')
s=s.replace('    wp.synchronize_stream(stream)\n    result=', "    wp.synchronize_stream(stream)\n    if profiler is not None:profiler.cudaProfilerStop()\n    if os.environ.get('WARPOWER_TOPOLOGY_DOT'):wp.capture_debug_dot_print(cap.graph,os.environ['WARPOWER_TOPOLOGY_DOT'],verbose=True)\n    result=")
s=s.replace('    np.testing.assert_array_equal(result[:,0]', '    np.testing.assert_array_equal(result[[2,3],21:24],0)\n    np.testing.assert_array_equal(result[:,0]')
p=w/'test_tangential_production_loop_v2.py';assert not p.exists();p.write_text(s)
s=(w/'check-tangential-production-loop-v1.py').read_text().replace('tangential-production-loop-v1','tangential-production-loop-v2')
p=w/'check-tangential-production-loop-v2.py';assert not p.exists();p.write_text(s)
